using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;

// Isolated editor-only visuals; original renderers and model outline weights remain untouched.
public sealed class CreatorSceneGizmo : MonoBehaviour {
 [Serializable] public sealed class EditEvent { public string id,phase,property; public float[] position,rotation,scale; }
 sealed class Shell { public Renderer source,copy; public GameObject objectCopy; }
 Camera view; Material shellMaterial; Material[] axisMaterials; GameObject moveRoot,scaleRoot,rotateRoot; Mesh arrowMesh; readonly List<Shell> shells=new List<Shell>();
 Transform target; Vector3 pivotLocal,selectedScale=Vector3.one; string selectionId="",mode="move",dragMode="move",modeToSend,awaitModeAck; bool editable,dragging,beginPending,endPending,movePending; int dragAxis; Vector3 initialPosition,dragPosition,initialScale,dragScale,initialLocalScale; Quaternion initialRotation,dragRotation; Vector2 mouseStart,projectedAxis; float axisLength,axisWorldLength; readonly Vector3[] axes={Vector3.right,Vector3.up,Vector3.forward};
 public void Configure(Camera camera,Shader shell,Shader axis){view=camera;shellMaterial=new Material(shell);shellMaterial.SetColor("_Color",new Color(1f,.57f,.09f,1));axisMaterials=new[]{new Material(axis),new Material(axis),new Material(axis)};axisMaterials[0].SetColor("_Color",new Color(.94f,.20f,.16f));axisMaterials[1].SetColor("_Color",new Color(.25f,.85f,.25f));axisMaterials[2].SetColor("_Color",new Color(.18f,.48f,1f));arrowMesh=MakeArrow();moveRoot=MakeAxisRoot(false);scaleRoot=MakeAxisRoot(true);rotateRoot=new GameObject("Creator rotation gizmo");for(int i=0;i<3;i++){var go=new GameObject("ring-"+i);go.transform.SetParent(rotateRoot.transform,false);var line=go.AddComponent<LineRenderer>();line.sharedMaterial=axisMaterials[i];line.useWorldSpace=true;line.positionCount=65;line.numCornerVertices=2;line.shadowCastingMode=ShadowCastingMode.Off;line.receiveShadows=false;}SetVisible(false);}
 GameObject MakeAxisRoot(bool cubes){var root=new GameObject(cubes?"Creator scale gizmo":"Creator translation gizmo");for(int i=0;i<3;i++){var line=GameObject.CreatePrimitive(PrimitiveType.Cylinder);line.name="axis-"+i;line.transform.SetParent(root.transform,false);Destroy(line.GetComponent<Collider>());line.GetComponent<Renderer>().sharedMaterial=axisMaterials[i];GameObject tip;if(cubes){tip=GameObject.CreatePrimitive(PrimitiveType.Cube);Destroy(tip.GetComponent<Collider>());}else{tip=new GameObject("arrow");tip.AddComponent<MeshFilter>().sharedMesh=arrowMesh;tip.AddComponent<MeshRenderer>();}tip.name="tip-"+i;tip.transform.SetParent(root.transform,false);tip.GetComponent<Renderer>().sharedMaterial=axisMaterials[i];}return root;}
 static Mesh MakeArrow(){const int n=16;var vertices=new Vector3[n+2];vertices[0]=new Vector3(0,1,0);vertices[1]=Vector3.zero;for(int i=0;i<n;i++){float a=i*Mathf.PI*2/n;vertices[i+2]=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));}var tris=new int[n*6];for(int i=0;i<n;i++){int k=i*6,j=2+(i+1)%n;tris[k]=0;tris[k+1]=j;tris[k+2]=i+2;tris[k+3]=1;tris[k+4]=i+2;tris[k+5]=j;}var mesh=new Mesh{name="Creator axis arrow"};mesh.vertices=vertices;mesh.triangles=tris;mesh.RecalculateNormals();return mesh;}
 void ClearShells(){foreach(var s in shells)if(s.objectCopy){s.objectCopy.SetActive(false);Destroy(s.objectCopy);}shells.Clear();}
 public void Select(string id,Transform next,bool canEdit,float[] scale){id=id??"";if(id!=selectionId||next!=target){ClearShells();selectionId=id;target=next;dragging=beginPending=endPending=movePending=false;awaitModeAck=null;modeToSend=null;if(target)foreach(var source in target.GetComponentsInChildren<Renderer>(true)){if(!source.enabled||source.forceRenderingOff||!source.gameObject.activeInHierarchy)continue;var go=new GameObject("Creator selection shell");Renderer copy=null;if(source is SkinnedMeshRenderer skin&&skin.sharedMesh){var s=go.AddComponent<SkinnedMeshRenderer>();s.sharedMesh=skin.sharedMesh;s.bones=skin.bones;s.rootBone=skin.rootBone;s.localBounds=skin.localBounds;s.updateWhenOffscreen=true;copy=s;}else if(source is MeshRenderer){var f=source.GetComponent<MeshFilter>();if(f&&f.sharedMesh){go.AddComponent<MeshFilter>().sharedMesh=f.sharedMesh;copy=go.AddComponent<MeshRenderer>();}}if(!copy){Destroy(go);continue;}int count=Math.Max(1,source.sharedMaterials.Length);var materials=new Material[count];for(int k=0;k<count;k++)materials[k]=shellMaterial;copy.sharedMaterials=materials;copy.shadowCastingMode=ShadowCastingMode.Off;copy.receiveShadows=false;copy.lightProbeUsage=LightProbeUsage.Off;copy.reflectionProbeUsage=ReflectionProbeUsage.Off;shells.Add(new Shell{source=source,copy=copy,objectCopy=go});}pivotLocal=Vector3.zero;if(target&&shells.Count>0){var bounds=shells[0].source.bounds;foreach(var shell in shells)if(shell.source)bounds.Encapsulate(shell.source.bounds);var local=target.InverseTransformPoint(bounds.center);if(!float.IsNaN(local.x)&&!float.IsNaN(local.y)&&!float.IsNaN(local.z)&&local.sqrMagnitude<10000)pivotLocal=local;}}editable=canEdit;if(!dragging&&!beginPending&&!endPending)selectedScale=ValidScale(scale)?new Vector3(scale[0],scale[1],scale[2]):Vector3.one;}
 static bool ValidScale(float[] a){return a!=null&&a.Length==3&&Array.TrueForAll(a,x=>!float.IsNaN(x)&&!float.IsInfinity(x)&&x>=.01f&&x<=100f);}
 public void SetMode(string value){if(value!="move"&&value!="rotate"&&value!="scale")value="move";if(awaitModeAck!=null){if(value!=awaitModeAck)return;awaitModeAck=null;}if(mode!=value){if(dragging)End();mode=value;}}
 void LocalMode(string value){if(mode==value)return;if(dragging)End();mode=value;modeToSend=value;awaitModeAck=value;}
 public string TakeMode(){var result=modeToSend;modeToSend=null;return result;}
 Vector3 Pivot(){return target?target.TransformPoint(pivotLocal):Vector3.zero;}
 Vector3 Axis(int i){return mode=="scale"&&target?target.rotation*axes[i]:axes[i];}
 static Vector3 RingPoint(int axis,float angle){float c=Mathf.Cos(angle),s=Mathf.Sin(angle);return axis==0?new Vector3(0,c,s):axis==1?new Vector3(c,0,s):new Vector3(c,s,0);}
 static float DistanceSegment(Vector2 mouse,Vector2 a,Vector2 b,out Vector2 tangent){var d=b-a;tangent=d;float n=d.sqrMagnitude;if(n<.01f)return Vector2.Distance(mouse,a);float u=Mathf.Clamp01(Vector2.Dot(mouse-a,d)/n);return Vector2.Distance(mouse,a+u*d);}
 void Update(){if(!target||!view)return;if(Input.GetKeyDown(KeyCode.W))LocalMode("move");if(Input.GetKeyDown(KeyCode.R))LocalMode("rotate");if(Input.GetKeyDown(KeyCode.S))LocalMode("scale");if(!editable){if(dragging)End();return;}if(Input.GetMouseButtonDown(0)&&!dragging&&!beginPending&&!endPending){var mouse=(Vector2)Input.mousePosition;var origin=view.WorldToScreenPoint(Pivot());if(origin.z<=0)return;float best=12;int chosen=-1;Vector2 chosenTangent=Vector2.zero;float world=WorldLength();for(int i=0;i<3;i++){if(mode=="rotate"){Vector3 previous=view.WorldToScreenPoint(Pivot()+RingPoint(i,0)*world*.82f);for(int k=1;k<=64;k++){Vector3 current=view.WorldToScreenPoint(Pivot()+RingPoint(i,k*Mathf.PI*2/64)*world*.82f);Vector2 tangent;float d=DistanceSegment(mouse,previous,current,out tangent);if(d<best&&tangent.sqrMagnitude>1){best=d;chosen=i;chosenTangent=tangent.normalized;}previous=current;}}else{var tip=view.WorldToScreenPoint(Pivot()+Axis(i)*world);Vector2 v=(Vector2)(tip-origin);float len=v.magnitude;float d;if(len<16f)d=Vector2.Distance(mouse,(Vector2)tip);else{Vector2 tangent;d=DistanceSegment(mouse,(Vector2)origin+v*.18f,tip,out tangent);}if(d<best){best=d;chosen=i;}}}if(chosen>=0)Begin(chosen,mouse,chosenTangent);}if(dragging&&Input.GetMouseButton(0))Move((Vector2)Input.mousePosition);if(dragging&&Input.GetMouseButtonUp(0))End();}
 float WorldLength(){if(!view||!target)return 1;float distance=Mathf.Max(.05f,Vector3.Distance(view.transform.position,Pivot()));return view.orthographic?view.orthographicSize*2f*90f/Mathf.Max(1,view.pixelHeight):2f*distance*Mathf.Tan(view.fieldOfView*Mathf.Deg2Rad*.5f)*90f/Mathf.Max(1,view.pixelHeight);}
 void Begin(int axis,Vector2 mouse,Vector2 tangent){if(!target||!editable)return;dragging=true;dragMode=mode;dragAxis=axis;initialPosition=target.position;dragPosition=initialPosition;initialRotation=target.rotation;dragRotation=initialRotation;initialScale=selectedScale;dragScale=initialScale;initialLocalScale=target.localScale;mouseStart=mouse;axisWorldLength=WorldLength();var a=view.WorldToScreenPoint(Pivot());var b=view.WorldToScreenPoint(Pivot()+Axis(axis)*axisWorldLength);projectedAxis=dragMode=="rotate"?(tangent.sqrMagnitude>.01f?tangent*90f:new Vector2(90,0)):(Vector2)(b-a);if(projectedAxis.sqrMagnitude<256f)projectedAxis=new Vector2(0,90);axisLength=projectedAxis.sqrMagnitude;beginPending=true;endPending=false;movePending=false;}
 void SetDelta(float value){if(!dragging)return;if(dragMode=="move")dragPosition=initialPosition+axes[dragAxis]*Mathf.Clamp(value,-100,100);else if(dragMode=="rotate")dragRotation=Quaternion.AngleAxis(Mathf.Clamp(value,-3600,3600),axes[dragAxis])*initialRotation;else{dragScale=initialScale;dragScale[dragAxis]=Mathf.Clamp(initialScale[dragAxis]*(1+value),.01f,100f);}movePending=true;}
 void Move(Vector2 mouse){if(!dragging||axisLength<81)return;float fraction=Vector2.Dot(mouse-mouseStart,projectedAxis)/axisLength;SetDelta(dragMode=="move"?fraction*axisWorldLength:dragMode=="rotate"?fraction*90f*(dragAxis==1?-1f:1f):fraction);}
 void End(){if(!dragging)return;dragging=false;endPending=true;movePending=false;}
 public void TestInput(string phase,int axis,float delta){if(phase=="key")LocalMode(axis==0?"move":axis==1?"rotate":"scale");else if(phase=="begin")Begin(axis,Vector2.zero,Vector2.right);else if(phase=="move")SetDelta(delta);else if(phase=="end")End();}
 public EditEvent TakeEvent(){if(beginPending){beginPending=false;return Event("begin");}if(endPending){endPending=false;return Event("end");}if(dragging&&movePending){movePending=false;return Event("move");}return null;}
 EditEvent Event(string phase){var p=phase=="begin"?initialPosition:dragPosition;var q=(phase=="begin"?initialRotation:dragRotation).eulerAngles;var s=phase=="begin"?initialScale:dragScale;return new EditEvent{id=selectionId,phase=phase,property=dragMode=="move"?"position":dragMode=="rotate"?"rotation":"scale",position=new[]{p.x,p.y,p.z},rotation=new[]{q.x,q.y,q.z},scale=new[]{s.x,s.y,s.z}};}
 void LateUpdate(){if(!moveRoot||!view)return;if(!target){SetVisible(false);return;}if(dragging||beginPending||endPending){if(dragMode=="move")target.position=dragPosition;else if(dragMode=="rotate")target.rotation=dragRotation;else target.localScale=Vector3.Scale(initialLocalScale,new Vector3(dragScale.x/initialScale.x,dragScale.y/initialScale.y,dragScale.z/initialScale.z));}foreach(var s in shells){if(!s.source||!s.copy)continue;s.objectCopy.SetActive(s.source.enabled&&!s.source.forceRenderingOff&&s.source.gameObject.activeInHierarchy);s.objectCopy.transform.SetPositionAndRotation(s.source.transform.position,s.source.transform.rotation);s.objectCopy.transform.localScale=s.source.transform.lossyScale;if(s.source is SkinnedMeshRenderer a&&s.copy is SkinnedMeshRenderer b&&a.sharedMesh){int n=a.sharedMesh.blendShapeCount;for(int i=0;i<n;i++)b.SetBlendShapeWeight(i,a.GetBlendShapeWeight(i));}}var p=Pivot();float size=WorldLength(),radius=size*.018f;SetVisible(true);GameObject root=mode=="scale"?scaleRoot:moveRoot;if(mode!="rotate")for(int i=0;i<3;i++){Vector3 axis=Axis(i);var line=root.transform.GetChild(i*2);line.position=p+axis*size*.5f;line.rotation=Quaternion.FromToRotation(Vector3.up,axis);line.localScale=new Vector3(radius,size*.5f,radius);var tip=root.transform.GetChild(i*2+1);tip.position=p+axis*(mode=="move"?size-radius*5f:size);tip.rotation=mode=="scale"?target.rotation:Quaternion.FromToRotation(Vector3.up,axis);tip.localScale=mode=="scale"?Vector3.one*radius*4f:new Vector3(radius*2.8f,radius*5f,radius*2.8f);}else for(int i=0;i<3;i++){var line=rotateRoot.transform.GetChild(i).GetComponent<LineRenderer>();line.startWidth=line.endWidth=radius*1.4f;for(int k=0;k<=64;k++)line.SetPosition(k,p+RingPoint(i,k*Mathf.PI*2/64)*size*.82f);}}
 public void SetVisible(bool visible){if(moveRoot)moveRoot.SetActive(visible&&target&&mode=="move");if(scaleRoot)scaleRoot.SetActive(visible&&target&&mode=="scale");if(rotateRoot)rotateRoot.SetActive(visible&&target&&mode=="rotate");foreach(var s in shells)if(s.objectCopy)s.objectCopy.SetActive(visible&&s.source&&s.source.enabled&&!s.source.forceRenderingOff&&s.source.gameObject.activeInHierarchy);}
 void OnDestroy(){ClearShells();if(moveRoot)Destroy(moveRoot);if(scaleRoot)Destroy(scaleRoot);if(rotateRoot)Destroy(rotateRoot);if(shellMaterial)Destroy(shellMaterial);if(arrowMesh)Destroy(arrowMesh);if(axisMaterials!=null)foreach(var m in axisMaterials)if(m)Destroy(m);}
}
